import { test, expect } from '@playwright/test';

test.describe('Password Change from Profile Settings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully change password with valid input', async ({ page }) => {
    // Verify initial password is displayed
    const passwordInput = page.getByLabel('Current Password');
    await expect(passwordInput).toBeVisible();

    // Verify new password fields are visible
    const newPasswordInput = page.getByLabel('New Password');
    await expect(newPasswordInput).toBeVisible();

    const confirmNewPasswordInput = page.getByLabel('Confirm New Password');
    await expect(confirmNewPasswordInput).toBeVisible();

    // Verify password change button is visible
    const changePasswordButton = page.getByRole('button', { name: /change password/i });
    await expect(changePasswordButton).toBeVisible();

    // Fill in current password
    await passwordInput.fill('123456');

    // Fill in new password
    await newPasswordInput.fill('NewSecurePassword123');

    // Fill in confirm password
    await confirmNewPasswordInput.fill('NewSecurePassword123');

    // Click change password button
    await changePasswordButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/password changed successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify profile page is still visible
    await expect(page).toBeVisible();
  });

  test('should display error when new passwords do not match', async ({ page }) => {
    // Verify initial password is displayed
    const passwordInput = page.getByLabel('Current Password');
    await expect(passwordInput).toBeVisible();

    // Verify new password fields are visible
    const newPasswordInput = page.getByLabel('New Password');
    await expect(newPasswordInput).toBeVisible();

    const confirmNewPasswordInput = page.getByLabel('Confirm New Password');
    await expect(confirmNewPasswordInput).toBeVisible();

    // Fill in current password
    await passwordInput.fill('123456');

    // Fill in new password
    await newPasswordInput.fill('NewSecurePassword123');

    // Fill in confirm password with a different value
    await confirmNewPasswordInput.fill('WrongConfirmPassword');

    // Click change password button
    const changePasswordButton = page.getByRole('button', { name: /change password/i });
    await expect(changePasswordButton).toBeVisible();
    await changePasswordButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/passwords do not match/i);
    await expect(errorMessage).toBeVisible();

    // Verify profile page is still visible
    await expect(page).toBeVisible();
  });
});
